import React, { useEffect,useRef, useMemo, useState } from "react";
import { adminApi } from "./api";
import { AdminCatalog } from "./admin-catalog";

type Section = "Обзор" | "Пользователи" | "Инвойсы" | "Кампании" | "Видеообучение" | "Коммуникации" | "Реклама" | "Тарифы" | "Шаблоны";
type OwnerSummary = {
  id:number; telegram_id:number; username:string; first_name:string; last_name:string;
  created_at:string; last_seen_at:string; plan:"free"|"business"; plan_name:string;
  subscription:null|{source:string;status:string;starts_at:string;ends_at:string|null;auto_renew:boolean};
  usage:{bots:number;channels:number;contacts:number}; paid_rub:string;
};
type OwnerDetail = {
  owner:OwnerSummary; subscription:any; bots:Array<any>; payments:Array<any>; admin_events:Array<any>;
};

const sections:Array<{name:Section;label:string;hint:string}> = [
  {name:"Обзор",label:"Обзор продукта",hint:"Ключевые показатели и здоровье продукта"},
  {name:"Пользователи",label:"Пользователи",hint:"Аккаунты, использование и подписки"},
  {name:"Инвойсы",label:"Инвойсы",hint:"Платежи, статусы и сверка"},
  {name:"Кампании",label:"Кампании",hint:"Deep links, атрибуция и выручка"},
  {name:"Видеообучение",label:"Видеообучение",hint:"Короткие уроки внутри продукта"},
  {name:"Шаблоны",label:"Шаблоны цепочек",hint:"Каталог, версии и публикация"},
  {name:"Коммуникации",label:"Коммуникации",hint:"Объявления внутри бота"},
  {name:"Реклама",label:"Free-реклама",hint:"Креативы, показы и клики"},
  {name:"Тарифы",label:"Тарифы и оплата",hint:"Цены, способы оплаты и готовность"},
];
const learningChapterNames:Record<string,string> = {
  first_launch:"Первый запуск",
  automation:"Автоматизация и рост",
  account:"Аккаунт",
};

const sectionCopy:Record<Section,{eyebrow:string;title:string;body:string;steps:string[]}> = {
  "Шаблоны":{eyebrow:"",title:"Шаблоны цепочек",body:"Добавляйте приветствия и прощания в общий каталог. Клиент получает независимую копию: изменение или скрытие шаблона не меняет его цепочки и доставки.",steps:["Создайте скрытую версию","Проверьте тексты, задержки и ссылки","Опубликуйте или уберите из каталога без потери истории"]},
  "Обзор":{eyebrow:"PRODUCT PULSE",title:"GramlyHello под контролем",body:"Живая картина продукта: владельцы, подключённая инфраструктура, доставки и оплаченные подписки. Выберите период — все показатели ниже пересчитаются по реальным данным.",steps:["Следите за ростом активных владельцев","Проверяйте долю Business","Разбирайте ошибки доставок до обращений клиентов"]},
  "Пользователи":{eyebrow:"CUSTOMER CONTROL",title:"Пользователи и подписки",body:"Найдите владельца по имени, username или Telegram ID, откройте карточку и управляйте его доступом. Любое изменение требует причины, записывается в security-аудит и приходит пользователю в Telegram.",steps:["Подарить Business на заданный срок","Продлить текущий период","Отключить автопродление или отозвать доступ"]},
  "Инвойсы":{eyebrow:"PAYMENT OPERATIONS",title:"Инвойсы и сверка",body:"Единый журнал Crypto Pay, Telegram Stars и ручных платежей. Статусы меняются только по доверенным событиям провайдера — здесь нельзя вручную подменить оплату.",steps:["Найдите счёт или владельца","Проверьте финансовую цепочку","Запустите безопасную сверку при расхождении"]},
  "Кампании":{eyebrow:"ACQUISITION",title:"Рекламные кампании",body:"Создавайте отдельную Telegram deep link для каждого размещения. Gramly фиксирует последний действующий переход до оплаты и сохраняет выручку со всех последующих продлений.",steps:["Задайте период и окно атрибуции","Передайте непрозрачную ссылку площадке","Сравнивайте клики, оплаты и активных клиентов"]},
  "Видеообучение":{eyebrow:"LEARNING",title:"Видеообучение",body:"Управляйте короткими уроками, которые доступны в owner-боте, Mini App и на лендинге. Неактивный ролик остаётся в истории, но не показывается пользователям.",steps:["Загрузите ролик на управляемый HTTPS-ресурс","Добавьте обложку и конкретное название","Проверьте ролик перед публикацией"]},
  "Коммуникации":{eyebrow:"MESSAGING",title:"Объявления",body:"Объявления доставляются выбранной аудитории один раз с повтором при временной ошибке.",steps:["Выберите аудиторию Free, Business или всех","Укажите точное время старта","Проверьте текст и ссылку перед запуском"]},
  "Реклама":{eyebrow:"FREE MONETISATION",title:"Реклама в Free-приветствиях",body:"Активные креативы выбираются случайно с учётом веса и добавляются в конец приветствия Free-пользователей. Здесь видны только реальные показы и зарегистрированные переходы.",steps:["Вес задаёт относительную частоту показа","CTA и URL заполняются только вместе","Отключайте креатив вместо удаления истории"]},
  "Тарифы":{eyebrow:"BILLING",title:"Тарифы и платёжный контур",body:"Управляйте ценой Business и доступными способами оплаты. Checkout включается только при полной конфигурации; статусы секретов показывают готовность, но никогда не раскрывают значения.",steps:["RUB используется для Crypto Pay","XTR — цена Telegram Stars","Referral base фиксирует базу партнёрской комиссии"]},
};

function Logo(){return <div className="logo"><span className="logo-mark">G</span><span>GramlyHello<small> CONTROL</small></span></div>}
function Status({ok,children}:{ok:boolean;children:React.ReactNode}){return <span className={`status ${ok?"ok":"warn"}`}><i/>{children}</span>}
function ErrorBox({message,onClose}:{message:string;onClose():void}){return <div className="error" role="alert"><div><strong>Не удалось выполнить действие</strong><span>{message}</span></div><button onClick={onClose}>×</button></div>}
function Metric({label,value,note}:{label:string;value:React.ReactNode;note?:string}){return <article className="control-metric"><span>{label}</span><strong>{value}</strong>{note&&<small>{note}</small>}</article>}
function formatDate(value?:string|null){if(!value)return "—";return new Intl.DateTimeFormat("ru-RU",{dateStyle:"medium",timeStyle:"short"}).format(new Date(value))}
function money(value:unknown){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(Number(value||0))+" ₽"}

function SectionIntro({section}:{section:Section}){const copy=sectionCopy[section];return <section className="control-intro"><div><span className="eyebrow">{copy.eyebrow}</span><h1>{copy.title}</h1><p>{copy.body}</p></div><ol>{copy.steps.map((item,index)=><li key={item}><span>{String(index+1).padStart(2,"0")}</span>{item}</li>)}</ol></section>}

function SparkBars({items,keyName}:{items:Array<any>;keyName:string}){const max=Math.max(1,...items.map(item=>Number(item[keyName]||0)));return <div className="spark-bars" aria-label="Динамика по дням">{items.length?items.map(item=><div key={item.date} title={`${item.date}: ${item[keyName]}`}><i style={{height:`${Math.max(5,Number(item[keyName]||0)/max*100)}%`}}/><span>{String(item.date).slice(5)}</span></div>):<p>За выбранный период событий пока нет.</p>}</div>}

function Dashboard({data,setDays}:{data:any;setDays(value:number):void}){const total=Object.values(data?.deliveries||{}).reduce((sum:number,value:any)=>sum+Number(value),0) as number;const failed=Number(data?.deliveries?.failed||0)+Number(data?.deliveries?.partial||0)+Number(data?.deliveries?.unreachable||0);const success=total?Math.round((total-failed)/total*100):0;const commercial=data?.commercial||{};return <><div className="period-control"><span>Период аналитики</span>{[7,30,90].map(day=><button className={data?.range_days===day?"active":""} onClick={()=>setDays(day)} key={day}>{day} дней</button>)}</div><div className="control-metrics"><Metric label="Владельцы" value={data?.owners?.total||0} note={`+${data?.owners?.new||0} за период`}/><Metric label="Активные платные" value={commercial.active_paid_clients||0} note="Business с действующим сроком"/><Metric label="Первая оплата" value={commercial.first_paid_30d||0} note="Новые платящие за 30 дней"/><Metric label="Churn" value={commercial.churned_7d||0} note="Потеряли последний активный бот/канал за 7 дней"/></div><div className="control-metrics secondary"><Metric label="WRR" value={money(commercial.weekly_revenue_run_rate_rub)} note="Расчётная годовая выручка / 52"/><Metric label="Расчётная цена" value={money(commercial.calculation_price_rub)} note="Не влияет на checkout"/><Metric label="Business" value={data?.business_active||0} note="Все активные Business"/><Metric label="Успешность" value={`${success}%`} note={`${total} цепочек за период`}/></div><div className="analytics-grid"><article className="analytics-panel"><header><div><span className="eyebrow">GROWTH</span><h2>Новые владельцы</h2></div><b>{data?.owners?.new||0}</b></header><SparkBars items={data?.series?.owners||[]} keyName="value"/></article><article className="analytics-panel"><header><div><span className="eyebrow">WEEKLY SNAPSHOTS</span><h2>Динамика WRR</h2></div><b>{money(commercial.weekly_revenue_run_rate_rub)}</b></header><SparkBars items={(data?.weekly_snapshots||[]).map((item:any)=>({...item,date:item.week_start}))} keyName="weekly_revenue_run_rate_rub"/></article></div><div className="control-metrics secondary"><Metric label="Активные боты" value={data?.infrastructure?.bots||0}/><Metric label="Каналы" value={data?.infrastructure?.channels||0}/><Metric label="Контакты" value={data?.infrastructure?.contacts||0}/><Metric label="Оплачено" value={money(data?.payments?.rub)} note={`${data?.payments?.count||0} платежей`}/></div></>}

function SubscriptionDialog({owner,onClose,onDone}:{owner:OwnerSummary;onClose():void;onDone():void}){const [action,setAction]=useState("grant_business");const [days,setDays]=useState(30);const [reason,setReason]=useState("");const [busy,setBusy]=useState(false);const descriptions:Record<string,string>={grant_business:"Выдаст Business бесплатно на новый срок и отключит автопродление.",extend_business:"Прибавит дни к текущей дате окончания. Если срок истёк — отсчёт начнётся сегодня.",cancel_renewal:"Оставит Business до конца оплаченного периода, но отменит следующее списание Stars.",revoke_now:"Сразу переведёт пользователя на Free. Оплаченные платежи и финансовая история останутся неизменными."};const submit=async(e:React.FormEvent)=>{e.preventDefault();if(!confirm(`Подтвердить действие для @${owner.username||owner.telegram_id}?`))return;setBusy(true);try{await adminApi(`/owners/${owner.id}/subscription`,{method:"POST",body:JSON.stringify({action,days:["grant_business","extend_business"].includes(action)?days:null,reason})});onDone()}finally{setBusy(false)}};return <div className="control-modal" role="dialog" aria-modal="true"><form onSubmit={submit}><header><div><span className="eyebrow">SUBSCRIPTION ACTION</span><h2>@{owner.username||owner.telegram_id}</h2></div><button type="button" onClick={onClose} aria-label="Закрыть">×</button></header><label>Действие<select value={action} onChange={e=>setAction(e.target.value)}><option value="grant_business">Подарить Business</option><option value="extend_business">Продлить Business</option><option value="cancel_renewal">Отключить автопродление</option><option value="revoke_now">Аннулировать Business сейчас</option></select><small>{descriptions[action]}</small></label>{["grant_business","extend_business"].includes(action)&&<label>Срок, дней<input type="number" min="1" max="3650" value={days} onChange={e=>setDays(Number(e.target.value))}/><small>Обычно 30 дней. Максимум — 10 лет.</small></label>}<label>Причина<textarea minLength={5} maxLength={500} required value={reason} onChange={e=>setReason(e.target.value)} placeholder="Например: компенсация за обращение #123"/><small>Причина попадёт в аудит и уведомление пользователя.</small></label><footer><button type="button" className="button ghost" onClick={onClose}>Отмена</button><button className={`button ${action==="revoke_now"?"danger":"acid"}`} disabled={busy}>{busy?"Применяем…":"Подтвердить"}</button></footer></form></div>}

type TransferPreview = {
  webhook:{status:string;pending_updates?:number}; pending_jobs:number; other_issues:string[];
  channels:Array<{id:number;title:string;greeting_active:boolean;incident:null|{approver_username?:string;sent_steps?:number;cancelled_steps?:number};admin_check:{status:string;bots:Array<{id:number;username:string}>}}>;
  recent_approvals:Array<{at:string;channel_id:number;approver_username:string}>;
};

function TransferDialog({source,bot,onClose,onDone}:{source:OwnerSummary;bot:any;onClose():void;onDone():void}){
  const [query,setQuery]=useState("");const [matches,setMatches]=useState<OwnerSummary[]>([]);const [target,setTarget]=useState<OwnerSummary|null>(null);
  const [reason,setReason]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState("");
  const [preview,setPreview]=useState<TransferPreview|null>(null);const [previewError,setPreviewError]=useState("");const [previewBusy,setPreviewBusy]=useState(true);const [acknowledged,setAcknowledged]=useState(false);
  const loadPreview=()=>{setPreviewBusy(true);setPreviewError("");adminApi<TransferPreview>(`/bots/${bot.id}/transfer-preview`).then(setPreview).catch(e=>setPreviewError((e as Error).message)).finally(()=>setPreviewBusy(false))};
  useEffect(()=>{loadPreview()},[bot.id]);
  useEffect(()=>{if(query.trim().length<2){setMatches([]);return}const timer=setTimeout(()=>adminApi<{items:OwnerSummary[]}>(`/owners?q=${encodeURIComponent(query)}&page_size=10`).then(data=>setMatches(data.items.filter(item=>item.id!==source.id))).catch(e=>setError((e as Error).message)),250);return()=>clearTimeout(timer)},[query,source.id]);
  const confirmed=preview?.channels.filter(channel=>channel.incident)||[];
  const possible=preview?.channels.filter(channel=>channel.admin_check.bots.length>0&&!channel.incident)||[];
  const needsAcknowledgement=confirmed.length>0||possible.length>0||Boolean(preview?.other_issues.length)||Boolean(preview?.recent_approvals.length)||preview?.webhook.status!=="ok";
  const submit=async(e:React.FormEvent)=>{e.preventDefault();if(!target||!preview||previewBusy||(needsAcknowledgement&&!acknowledged))return;setBusy(true);setError("");try{await adminApi(`/bots/${bot.id}/transfer`,{method:"POST",body:JSON.stringify({target_owner_id:target.id,reason})});onDone()}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
  return <div className="control-modal" role="dialog" aria-modal="true" aria-labelledby="transfer-title"><form onSubmit={submit}><header><div><span className="eyebrow">BOT TRANSFER</span><h2 id="transfer-title">Передать @{bot.username||bot.display_name}</h2></div><button type="button" onClick={onClose} aria-label="Закрыть">×</button></header>
    <p>Каналы, цепочки, база и аналитика перейдут новому владельцу. Платежи и подписка @{source.username||source.telegram_id} останутся без изменений.</p>
    <section className="transfer-preflight" aria-live="polite"><h3>Проверка перед передачей</h3>
      {previewBusy?<p>Проверяем webhook, каналы и доставки…</p>:previewError?<p role="alert">Проверка недоступна: {previewError} <button type="button" onClick={loadPreview}>Повторить</button></p>:preview&&<>
        <p>Webhook: {preview.webhook.status==="ok"?"адрес настроен":preview.webhook.status==="mismatch"?"адрес отличается":"не удалось проверить"} · активных каналов: {preview.channels.length} · заданий в работе: {preview.pending_jobs}</p>
        {confirmed.map(channel=><p className="transfer-warning" key={channel.id}><b>{channel.title}: подтверждённый конфликт.</b> Заявку принимал {channel.incident?.approver_username?`@${channel.incident.approver_username}`:"другой бот"}. Приветствие {channel.greeting_active?"включено":"отключено"}.</p>)}
        {possible.map(channel=><p className="transfer-caution" key={channel.id}><b>{channel.title}: возможный конфликт.</b> Право принимать заявки есть у {channel.admin_check.bots.map(item=>item.username?`@${item.username}`:`бота ${item.id}`).join(", ")}. Автоприём этим не подтверждён.</p>)}
        {preview.other_issues.length>0&&<p className="transfer-warning">Есть другие проблемы доставки: {preview.other_issues.join(", ")}.</p>}
        {preview.channels.some(channel=>channel.admin_check.status!=="checked")&&<p>Права части каналов проверить не удалось. Их состояние остаётся неизвестным.</p>}
        {preview.recent_approvals.length>0&&<p>Последнее подтверждённое одобрение другим ботом: {preview.channels.find(channel=>channel.id===preview.recent_approvals[0].channel_id)?.title||`канал #${preview.recent_approvals[0].channel_id}`} · {preview.recent_approvals[0].approver_username?`@${preview.recent_approvals[0].approver_username}`:"другой бот"} · {formatDate(preview.recent_approvals[0].at)}.</p>}
        {!needsAcknowledgement&&<p>Подтверждённых конфликтов не найдено. Telegram-настройки могут измениться после проверки.</p>}
      </>}
    </section>
    <label>Получатель<input value={query} onChange={e=>{setQuery(e.target.value);setTarget(null)}} placeholder="@username или Telegram ID"/><small>Выберите точную запись из результатов.</small></label>{matches.length>0&&<div className="transfer-results">{matches.map(item=><button type="button" className={target?.id===item.id?"selected":""} key={item.id} onClick={()=>{setTarget(item);setQuery(`@${item.username||item.telegram_id}`)}}><b>@{item.username||item.telegram_id}</b><span>{[item.first_name,item.last_name].filter(Boolean).join(" ")} · {item.usage.bots} ботов · {item.plan_name}</span></button>)}</div>}
    <label>Причина<textarea minLength={5} maxLength={500} required value={reason} onChange={e=>setReason(e.target.value)} placeholder="Например: передача по запросу владельца"/><small>Причина попадёт в security-аудит и уведомление.</small></label>
    {target&&<div className="transfer-summary"><b>После подтверждения</b><span>@{bot.username||bot.display_name} → @{target.username||target.telegram_id}</span><span>Credential и webhook сохраняются</span></div>}
    {preview&&needsAcknowledgement&&<label className="transfer-ack"><input type="checkbox" checked={acknowledged} onChange={e=>setAcknowledged(e.target.checked)}/> Ознакомился с проблемами доставки. Передача их не устранит.</label>}
    {error&&<div className="error" role="alert">{error}</div>}<footer><button type="button" className="button ghost" onClick={onClose}>Отмена</button><button className="button danger" disabled={!target||!preview||previewBusy||busy||(needsAcknowledgement&&!acknowledged)}>{busy?"Передаём…":"Передать бота"}</button></footer>
  </form></div>
}

function OwnerDrawer({owner,onClose,onManage,onTransfer}:{owner:OwnerSummary;onClose():void;onManage():void;onTransfer(bot:any):void}){const [detail,setDetail]=useState<OwnerDetail|null>(null);useEffect(()=>{adminApi<OwnerDetail>(`/owners/${owner.id}`).then(setDetail)},[owner.id]);return <div className="owner-drawer"><header><button onClick={onClose}>← К списку</button><span className="eyebrow">OWNER #{owner.id}</span></header><div className="owner-identity"><span>{(owner.first_name||owner.username||"U").slice(0,1).toUpperCase()}</span><div><h2>{[owner.first_name,owner.last_name].filter(Boolean).join(" ")||"Без имени"}</h2><p>@{owner.username||"username не указан"} · <code>{owner.telegram_id}</code></p></div></div><div className="drawer-status"><Status ok={owner.plan==="business"}>{owner.plan_name}</Status><button className="button acid" onClick={onManage}>Управлять подпиской</button></div><dl><div><dt>Создан</dt><dd>{formatDate(owner.created_at)}</dd></div><div><dt>Последняя активность</dt><dd>{formatDate(owner.last_seen_at)}</dd></div><div><dt>Оплачено всего</dt><dd>{money(owner.paid_rub)}</dd></div><div><dt>Использование</dt><dd>{owner.usage.bots} ботов · {owner.usage.channels} каналов · {owner.usage.contacts} контактов</dd></div></dl><section><h3>Подключённые боты</h3>{detail?.bots?.length?detail.bots.map(bot=><div className="drawer-row bot-admin-row" key={bot.id}><span><b>@{bot.username||bot.display_name}</b><small>{bot.webhook_configured?"Webhook online":"Webhook требует внимания"}</small></span><div><Status ok={bot.is_active}>{bot.is_active?"Активен":"Остановлен"}</Status><button className="button ghost" onClick={()=>onTransfer(bot)}>Передать</button></div></div>):<p>Пользователь ещё не подключил бота.</p>}</section><section><h3>Подписка</h3>{detail?.subscription?<div className="drawer-card"><b>{detail.subscription.plan_name}</b><span>{detail.subscription.source} · {detail.subscription.status}</span><span>до {formatDate(detail.subscription.ends_at)}</span><span>автопродление: {detail.subscription.auto_renew?"включено":"выключено"}</span></div>:<p>Активной записи нет — применяется Free.</p>}</section><section><h3>Последние платежи</h3>{detail?.payments?.length?detail.payments.map(payment=><div className="drawer-row" key={payment.id}><span><b>{money(payment.amount_rub)}</b><small>{payment.provider} · {formatDate(payment.created_at)}</small></span><Status ok={payment.status==="paid"}>{payment.status}</Status></div>):<p>Подтверждённых платежей пока нет.</p>}</section><section><h3>Административный аудит</h3>{detail?.admin_events?.length?detail.admin_events.map((event,index)=><div className="audit-row" key={index}><b>{event.message}</b><span>{formatDate(event.created_at)} · {event.context?.admin}</span><small>{event.context?.reason}</small></div>):<p>Ручных изменений не было.</p>}</section></div>}

function Owners({refreshToken}:{refreshToken:number}){const [data,setData]=useState<{items:OwnerSummary[];total:number;page:number;page_size:number}>({items:[],total:0,page:1,page_size:25});const [q,setQ]=useState("");const [plan,setPlan]=useState("all");const [page,setPage]=useState(1);const [selected,setSelected]=useState<OwnerSummary|null>(null);const [manage,setManage]=useState(false);const [transferBot,setTransferBot]=useState<any|null>(null);const load=()=>adminApi<any>(`/owners?q=${encodeURIComponent(q)}&plan=${plan}&page=${page}`).then(setData);useEffect(()=>{const timer=setTimeout(()=>void load(),200);return()=>clearTimeout(timer)},[q,plan,page,refreshToken]);const pages=Math.max(1,Math.ceil(data.total/data.page_size));return <><div className="filter-bar"><label>Поиск<input value={q} onChange={e=>{setQ(e.target.value);setPage(1)}} placeholder="Имя, @username или Telegram ID"/></label><label>Тариф<select value={plan} onChange={e=>{setPlan(e.target.value);setPage(1)}}><option value="all">Все пользователи</option><option value="business">Business</option><option value="free">Free</option></select></label><span>Найдено: <b>{data.total}</b></span></div><div className="owner-table"><div className="table-head"><span>Пользователь</span><span>Тариф</span><span>Использование</span><span>Активность</span><span/></div>{data.items.map(owner=><button className="owner-row" key={owner.id} onClick={()=>setSelected(owner)}><span className="user-cell"><i>{(owner.first_name||owner.username||"U").slice(0,1).toUpperCase()}</i><span><b>{[owner.first_name,owner.last_name].filter(Boolean).join(" ")||"Без имени"}</b><small>@{owner.username||"—"} · {owner.telegram_id}</small></span></span><Status ok={owner.plan==="business"}>{owner.plan_name}</Status><span>{owner.usage.bots} ботов · {owner.usage.channels} каналов<br/><small>{owner.usage.contacts} контактов</small></span><span>{formatDate(owner.last_seen_at)}</span><span>→</span></button>)}</div><div className="pagination"><button disabled={page<=1} onClick={()=>setPage(page-1)}>← Назад</button><span>{page} / {pages}</span><button disabled={page>=pages} onClick={()=>setPage(page+1)}>Вперёд →</button></div>{selected&&<OwnerDrawer owner={selected} onClose={()=>setSelected(null)} onManage={()=>setManage(true)} onTransfer={setTransferBot}/>} {selected&&manage&&<SubscriptionDialog owner={selected} onClose={()=>setManage(false)} onDone={()=>{setManage(false);setSelected(null);void load()}}/>}{selected&&transferBot&&<TransferDialog source={selected} bot={transferBot} onClose={()=>setTransferBot(null)} onDone={()=>{setTransferBot(null);setSelected(null);void load()}}/>}</>}

type Invoice = {
  id:number;provider_invoice_id:string|null;provider:string;status:string;amount_rub:string;
  original_amount:string|null;original_currency:string;paid_asset:string|null;exchange_rate_rub:string|null;
  invoice_url:string;period_days:number;created_at:string;expires_at:string;paid_at:string|null;refunded_at:string|null;
  owner:{id:number;telegram_id:number;username:string;name:string};plan:{id:number;slug:string;name:string};
};
type InvoiceDetail = Invoice & {subscription:any;ledger:Array<any>;verification:any;audit:Array<any>};
const invoiceStatus:Record<string,string>={created:"Ожидает",paid:"Оплачен",expired:"Истёк",refunded:"Возвращён",failed:"Ошибка"};
const providerName:Record<string,string>={crypto_pay:"Crypto Pay",telegram_stars:"Telegram Stars",manual:"Ручной"};

function InvoiceCountdown({invoice}:{invoice:Invoice}){const [now,setNow]=useState(Date.now());useEffect(()=>{if(invoice.status!=="created")return;const timer=window.setInterval(()=>setNow(Date.now()),1000);return()=>window.clearInterval(timer)},[invoice.status]);if(invoice.status!=="created")return null;const seconds=Math.max(0,Math.ceil((new Date(invoice.expires_at).getTime()-now)/1000));return <small>{seconds?`осталось ${String(Math.floor(seconds/60)).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`:"истекает"}</small>}

function InvoiceDrawer({invoice,onClose,onReconciled}:{invoice:Invoice;onClose():void;onReconciled():void}){
  const [detail,setDetail]=useState<InvoiceDetail|null>(null);const [busy,setBusy]=useState(false);const [message,setMessage]=useState("");
  useEffect(()=>{adminApi<InvoiceDetail>(`/payments/${invoice.id}`).then(setDetail)},[invoice.id]);
  const reconcile=async()=>{setBusy(true);setMessage("");try{const result=await adminApi<{detail:string}>(`/payments/${invoice.id}/reconcile`,{method:"POST"});setMessage(result.detail);setDetail(await adminApi(`/payments/${invoice.id}`));onReconciled()}catch(e){setMessage((e as Error).message)}finally{setBusy(false)}};
  return <div className="owner-drawer invoice-drawer"><header><button onClick={onClose}>← К инвойсам</button><span className="eyebrow">INVOICE #{invoice.id}</span></header><div className="owner-identity"><span>₽</span><div><h2>{money(invoice.amount_rub)}</h2><p>{providerName[invoice.provider]||invoice.provider} · {invoiceStatus[invoice.status]||invoice.status}</p></div></div><div className="drawer-status"><Status ok={invoice.status==="paid"}>{invoiceStatus[invoice.status]||invoice.status}</Status><InvoiceCountdown invoice={detail||invoice}/>{invoice.provider!=="manual"&&<button className="button acid" disabled={busy} onClick={()=>void reconcile()}>{busy?"Сверяем…":"Сверить с провайдером"}</button>}</div>{message&&<p className="reconcile-result">{message}</p>}<dl><div><dt>Владелец</dt><dd>{invoice.owner.name||"Без имени"} · @{invoice.owner.username||"—"}</dd></div><div><dt>Telegram ID</dt><dd><code>{invoice.owner.telegram_id}</code></dd></div><div><dt>Тариф</dt><dd>{invoice.plan.name} · {invoice.period_days} дней</dd></div><div><dt>Provider invoice</dt><dd><code>{invoice.provider_invoice_id||"не присвоен"}</code></dd></div><div><dt>Создан</dt><dd>{formatDate(invoice.created_at)}</dd></div><div><dt>Истекает</dt><dd>{formatDate(invoice.expires_at)}</dd></div><div><dt>Оплачен</dt><dd>{formatDate(invoice.paid_at)}</dd></div><div><dt>Исходная сумма</dt><dd>{invoice.original_amount?`${invoice.original_amount} ${invoice.original_currency}`:"—"}</dd></div><div><dt>Asset / курс</dt><dd>{invoice.paid_asset||"—"} · {invoice.exchange_rate_rub||"—"}</dd></div></dl>{invoice.invoice_url&&<a className="button ghost invoice-link" href={invoice.invoice_url} target="_blank" rel="noreferrer">Открыть безопасную ссылку ↗</a>}<section><h3>Подписка</h3>{detail?.subscription?<div className="drawer-card"><b>{detail.subscription.status}</b><span>{detail.subscription.source} · до {formatDate(detail.subscription.ends_at)}</span><span>{detail.subscription.matches_invoice?"Связь с invoice подтверждена":"Требуется проверка связи"}</span></div>:<p>Связанной подписки нет.</p>}</section><section><h3>Финансовый ledger</h3>{detail?.ledger?.length?detail.ledger.map(item=><div className="drawer-row" key={item.id}><span><b>{item.type}</b><small>{item.reason||"Без комментария"}</small></span><span>{money(item.amount_rub)}<small>{formatDate(item.created_at)}</small></span></div>):<p>Проводок для инвойса нет.</p>}</section><section><h3>Проверка</h3><div className="drawer-card"><b>{detail?.verification?.has_provider_reference?"Provider reference сохранён":"Provider reference отсутствует"}</b><span>{detail?.verification?.snapshot?.snapshot_hash?`Snapshot ${String(detail.verification.snapshot.snapshot_hash).slice(0,12)}…`:"Без подтверждённого snapshot"}</span></div></section><section><h3>Аудит сверок</h3>{detail?.audit?.length?detail.audit.map((item,index)=><div className="audit-row" key={index}><b>{item.message}</b><span>{formatDate(item.created_at)} · {item.context?.admin}</span><small>{item.context?.detail}</small></div>):<p>Ручных сверок ещё не было.</p>}</section></div>
}

function Invoices(){
  const [data,setData]=useState<any>({items:[],total:0,page:1,page_size:25,summary:{}});const [q,setQ]=useState("");const [status,setStatus]=useState("active");const [provider,setProvider]=useState("all");const [plan,setPlan]=useState("all");const [sort,setSort]=useState("created_desc");const [from,setFrom]=useState("");const [to,setTo]=useState("");const [page,setPage]=useState(1);const [selected,setSelected]=useState<Invoice|null>(null);const [refresh,setRefresh]=useState(0);
  const params=useMemo(()=>{const value=new URLSearchParams({q,payment_status:status,provider,plan,sort,page:String(page)});if(from)value.set("created_from",new Date(`${from}T00:00:00`).toISOString());if(to)value.set("created_to",new Date(`${to}T23:59:59`).toISOString());return value},[q,status,provider,plan,sort,from,to,page]);
  useEffect(()=>{const timer=setTimeout(()=>adminApi<any>(`/payments?${params}`).then(setData),200);return()=>clearTimeout(timer)},[params,refresh]);
  const resetPage=()=>setPage(1);const pages=Math.max(1,Math.ceil((data.total||0)/(data.page_size||25)));const exportUrl=`/api/admin/v1/payments/export.csv?${params}`;
  return <><div className="control-metrics secondary"><Metric label="Инвойсы" value={data.summary?.count||0}/><Metric label="Оплачено" value={money(data.summary?.paid_rub)}/><Metric label="Ожидается" value={money(data.summary?.pending_rub)}/><Metric label="Ошибки / истёкшие" value={data.summary?.errors||0}/></div><div className="invoice-filters"><label>Поиск<input value={q} onChange={e=>{setQ(e.target.value);resetPage()}} placeholder="Пользователь, Telegram ID или invoice ID"/></label><label>Статус<select value={status} onChange={e=>{setStatus(e.target.value);resetPage()}}><option value="active">Рабочий список</option><option value="all">Все, включая архив</option><option value="unpaid">Не оплачено</option><option value="created">Ожидает</option><option value="paid">Оплачен</option><option value="expired">Истёк</option><option value="refunded">Возвращён</option><option value="failed">Ошибка</option></select></label><label>Провайдер<select value={provider} onChange={e=>{setProvider(e.target.value);resetPage()}}><option value="all">Все провайдеры</option><option value="crypto_pay">Crypto Pay</option><option value="telegram_stars">Telegram Stars</option><option value="manual">Ручной</option></select></label><label>Тариф<select value={plan} onChange={e=>{setPlan(e.target.value);resetPage()}}><option value="all">Все тарифы</option><option value="business">Business</option><option value="free">Free</option></select></label><label>От<input type="date" value={from} onChange={e=>{setFrom(e.target.value);resetPage()}}/></label><label>До<input type="date" value={to} onChange={e=>{setTo(e.target.value);resetPage()}}/></label><label>Сортировка<select value={sort} onChange={e=>setSort(e.target.value)}><option value="created_desc">Сначала новые</option><option value="created_asc">Сначала старые</option><option value="paid_desc">Недавно оплаченные</option><option value="amount_desc">Сумма по убыванию</option><option value="amount_asc">Сумма по возрастанию</option></select></label><a className="button ghost" href={exportUrl}>Скачать CSV</a></div><div className="invoice-table"><div className="invoice-head"><span>Инвойс</span><span>Владелец</span><span>Провайдер</span><span>Сумма</span><span>Статус</span><span>Создан</span></div>{data.items?.map((invoice:Invoice)=><button className="invoice-row" key={invoice.id} onClick={()=>setSelected(invoice)}><span><b>#{invoice.id}</b><small>{invoice.provider_invoice_id||"ID ожидается"}</small></span><span><b>{invoice.owner.name||`@${invoice.owner.username}`||"Без имени"}</b><small>{invoice.owner.telegram_id}</small></span><span>{providerName[invoice.provider]||invoice.provider}</span><span><b>{money(invoice.amount_rub)}</b><small>{invoice.original_amount?`${invoice.original_amount} ${invoice.original_currency}`:""}</small></span><span><Status ok={invoice.status==="paid"}>{invoiceStatus[invoice.status]||invoice.status}</Status><InvoiceCountdown invoice={invoice}/></span><span>{formatDate(invoice.created_at)}</span></button>)}</div>{!data.items?.length&&<div className="skeleton">По текущим фильтрам инвойсов нет.</div>}<div className="pagination"><button disabled={page<=1} onClick={()=>setPage(page-1)}>← Назад</button><span>{page} / {pages} · найдено {data.total||0}</span><button disabled={page>=pages} onClick={()=>setPage(page+1)}>Вперёд →</button></div>{selected&&<InvoiceDrawer invoice={selected} onClose={()=>setSelected(null)} onReconciled={()=>setRefresh(value=>value+1)}/>}</>;
}

function Field({label,help,children}:{label:string;help:string;children:React.ReactNode}){return <label className="control-field"><span>{label}</span>{children}<small>{help}</small></label>}
function Toggle({active,onClick}:{active:boolean;onClick():void}){return <button className={`toggle ${active?"on":""}`} onClick={onClick} aria-label={active?"Отключить":"Включить"}><i/></button>}

function RequiredChannel({value,reload}:{value:any;reload():Promise<void>}){const save=async(event:React.FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);await adminApi("/required-channel",{method:"POST",body:JSON.stringify({enabled:data.get("enabled")==="on",channel_id:Number(data.get("channel_id")),title:data.get("title"),url:data.get("url")})});await reload()};return <form className="pricing-form" onSubmit={save}><header><div><span className="eyebrow">OWNER ACCESS GATE</span><h2>Обязательный новостной канал</h2></div><Status ok={Boolean(value?.enabled)}>{value?.enabled?"Включён":"Выключен"}</Status></header><p>Gate применяется к owner-боту и Mini App. Статус подписки проверяется напрямую через Telegram и обновляется по chat_member.</p><div><Field label="Telegram channel ID" help="Отрицательный ID супергруппы или канала. Бот должен быть администратором."><input name="channel_id" type="number" required defaultValue={value?.channel_id||-1004404255750}/></Field><Field label="Название" help="Показывается на экране обязательной подписки."><input name="title" required defaultValue={value?.title||"GRAMLY | Новости"}/></Field><Field label="Ссылка приглашения" help="Публичная или приватная HTTPS-ссылка t.me."><input name="url" type="url" required defaultValue={value?.url||"https://t.me/+gSu2vmXMeWBmZjI6"}/></Field></div><label className="check"><input name="enabled" type="checkbox" defaultChecked={Boolean(value?.enabled)}/> Требовать подписку для работы с продуктом</label><button className="button acid">Сохранить gate</button></form>}

function ContentAdmin({content,reload,submit}:{content:any;reload():Promise<void>;submit(e:React.FormEvent<HTMLFormElement>,path:string):Promise<void>}){
  const toggle=async(type:string,id:number,active:boolean)=>{await adminApi(`/resources/${type}/${id}/active`,{method:"POST",body:JSON.stringify({is_active:!active})});await reload()};
  return <>
    <div className="admin-grid">
      <form onSubmit={e=>void submit(e,"/learning-videos")}><h2>Новое видео</h2><p>Короткий урок для встроенного быстрого старта.</p><Field label="Slug" help="Например connect-bot."><input name="slug" required/></Field><Field label="Название" help="Конкретный результат урока."><input name="title" required/></Field><Field label="Video URL" help="Публичная HTTPS-ссылка CDN."><input name="video_url" type="url" required/></Field><Field label="Обложка" help="Необязательная HTTPS-ссылка."><input name="poster_url" type="url"/></Field><Field label="Описание" help="Одно короткое предложение."><textarea name="description"/></Field><Field label="Длительность, сек." help="Показывается рядом с уроком."><input name="duration_seconds" type="number" min="0" defaultValue="60"/></Field><Field label="Глава" help="Определяет место урока в маршруте."><select name="chapter_key" defaultValue="first_launch"><option value="first_launch">Первый запуск</option><option value="automation">Автоматизация и рост</option><option value="account">Аккаунт</option></select></Field><Field label="Feature key" help="home, bots, flows, audience или broadcasts."><input name="feature_key" defaultValue="home"/></Field><Field label="Порядок" help="Меньшее число показывается раньше."><input name="sort_order" type="number" defaultValue="100"/></Field><input name="is_active" type="hidden" value="true"/><button className="button acid">Добавить видео</button></form>
      <div className="records">{content?.videos?.map((item:any)=><article key={item.id}><header><div><strong>{item.title}</strong><span>{learningChapterNames[item.chapter_key]||item.chapter_key} · {item.feature_key} · {item.duration_seconds} сек.</span></div><Toggle active={item.is_active} onClick={()=>void toggle("learning-video",item.id,item.is_active)}/></header><p>{item.description}</p><a href={item.video_url} target="_blank" rel="noreferrer">Открыть видео ↗</a></article>)}</div>
    </div>
  </>;
}

function Communications({content,reload,submit}:{content:any;reload():Promise<void>;submit(e:React.FormEvent<HTMLFormElement>,path:string):Promise<void>}){const toggle=async(type:string,id:number,active:boolean)=>{await adminApi(`/resources/${type}/${id}/active`,{method:"POST",body:JSON.stringify({is_active:!active})});await reload()};return <div className="admin-grid"><form onSubmit={e=>void submit(e,"/announcements")}><h2>Новое объявление</h2><p>Сообщение попадёт в надёжную очередь и будет доставлено один раз.</p><Field label="Заголовок" help="Коротко назовите изменение или событие."><input name="title" required/></Field><Field label="Текст" help="До 4096 символов, без HTML."><textarea name="body" required/></Field><Field label="Аудитория" help="Кому будет назначена доставка."><select name="audience"><option value="all">Все</option><option value="free">Только Free</option><option value="business">Только Business</option></select></Field><Field label="Начало" help="Локальное время браузера будет переведено в UTC."><input name="starts_at" type="datetime-local" required/></Field><Field label="Текст кнопки" help="Оставьте оба поля пустыми, если кнопка не нужна."><input name="button_text"/></Field><Field label="URL кнопки" help="Публичная HTTPS-ссылка."><input name="button_url" type="url"/></Field><button className="button acid">Запланировать</button></form><div className="records">{content?.announcements?.map((item:any)=><article key={item.id}><header><div><strong>{item.title}</strong><span>{item.audience} · {formatDate(item.starts_at)}</span></div><Toggle active={item.is_active} onClick={()=>void toggle("announcement",item.id,item.is_active)}/></header><p>{item.body}</p></article>)}</div></div>}

function Advertising({ads,reload,submit}:{ads:any;reload():Promise<void>;submit(e:React.FormEvent<HTMLFormElement>,path:string):Promise<void>}){const toggle=async(id:number,active:boolean)=>{await adminApi(`/resources/advertising/${id}/active`,{method:"POST",body:JSON.stringify({is_active:!active})});await reload()};const impressions=(ads?.creatives||[]).reduce((n:number,item:any)=>n+item.impressions,0);const clicks=(ads?.creatives||[]).reduce((n:number,item:any)=>n+item.clicks,0);return <><div className="control-metrics secondary"><Metric label="Креативы" value={ads?.creatives?.length||0}/><Metric label="Активные" value={ads?.creatives?.filter((x:any)=>x.is_active).length||0}/><Metric label="Показы" value={impressions}/><Metric label="CTR" value={impressions?`${(clicks/impressions*100).toFixed(1)}%`:"0%"}/></div><div className="admin-grid"><form onSubmit={e=>void submit(e,"/advertising")}><h2>Новый Free-креатив</h2><p>Текст добавится в конец реального приветственного сообщения.</p><Field label="Внутреннее название" help="Видно только владельцам продукта."><input name="name" required/></Field><Field label="Рекламный текст" help="Короткий самостоятельный оффер без вводящих в заблуждение обещаний."><textarea name="text" required/></Field><Field label="CTA" help="Подпись кнопки; заполняется вместе с URL."><input name="cta_text"/></Field><Field label="CTA URL" help="HTTPS-ссылка для учёта переходов."><input name="cta_url" type="url"/></Field><Field label="Вес" help="Относительная частота: 2 показывается примерно вдвое чаще 1."><input name="weight" type="number" min="1" max="1000" defaultValue="1"/></Field><input name="is_active" type="hidden" value="true"/><button className="button acid">Добавить креатив</button></form><div className="records">{ads?.creatives?.map((item:any)=><article key={item.id}><header><div><strong>{item.name}</strong><span>{item.impressions} показов · {item.clicks} кликов · вес {item.weight}</span></div><Toggle active={item.is_active} onClick={()=>void toggle(item.id,item.is_active)}/></header><p>{item.text}</p></article>)}</div></div></>}

type Campaign = {id:number;name:string;starts_at:string;ends_at:string|null;attribution_window_days:number;is_active:boolean;deep_link:string;metrics:{clicks:number;unique_visitors:number;new_free:number;paid_clients:number;active_clients:number;revenue_rub:string;click_to_paid_percent:number}};

function Campaigns(){const [data,setData]=useState<{items:Campaign[];total:number;page_size:number}>({items:[],total:0,page_size:25});const [q,setQ]=useState("");const [state,setState]=useState("all");const [from,setFrom]=useState("");const [to,setTo]=useState("");const [busy,setBusy]=useState(false);const query=()=>new URLSearchParams({q,state,...(from?{starts_from:new Date(from).toISOString()}:{}),...(to?{starts_to:new Date(to).toISOString()}:{} )});const load=()=>adminApi<any>(`/campaigns?${query()}`).then(setData);useEffect(()=>{const timer=setTimeout(()=>void load(),200);return()=>clearTimeout(timer)},[q,state,from,to]);const create=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);const form=new FormData(e.currentTarget);try{await adminApi("/campaigns",{method:"POST",body:JSON.stringify({name:form.get("name"),starts_at:new Date(String(form.get("starts_at"))).toISOString(),ends_at:form.get("ends_at")?new Date(String(form.get("ends_at"))).toISOString():null,attribution_window_days:Number(form.get("attribution_window_days")),is_active:true})});e.currentTarget.reset();await load()}finally{setBusy(false)}};const copy=async(value:string)=>{await navigator.clipboard.writeText(value)};return <><div className="invoice-filters"><label>Поиск<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Название кампании"/></label><label>Статус<select value={state} onChange={e=>setState(e.target.value)}><option value="all">Все кампании</option><option value="active">Активные</option><option value="scheduled">Запланированные</option><option value="ended">Завершённые</option></select></label><label>Начало от<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Начало до<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><a className="button ghost" href={`/api/admin/v1/campaigns/export.csv?${query()}`}>Скачать CSV</a></div><p className="campaign-total">Найдено кампаний: <b>{data.total}</b></p><div className="admin-grid"><form onSubmit={create}><h2>Новая кампания</h2><p>Для каждого размещения создаётся уникальная ссылка. Окно атрибуции определяет, сколько дней переход может получить оплату.</p><Field label="Название" help="Например: Telegram Ads · август. Видно только администраторам."><input name="name" required maxLength={128}/></Field><Field label="Начало" help="До этой даты переходы не учитываются."><input name="starts_at" type="datetime-local" required/></Field><Field label="Окончание" help="После окончания история сохраняется, но новая атрибуция не создаётся."><input name="ends_at" type="datetime-local"/></Field><Field label="Окно атрибуции, дней" help="Last-touch среди действующих кампаний. Обычно 7–30 дней."><input name="attribution_window_days" type="number" min="1" max="365" defaultValue="30" required/></Field><button className="button acid" disabled={busy}>{busy?"Создаём…":"Создать кампанию"}</button></form><div className="records campaign-records">{data.items.length?data.items.map(item=><article key={item.id}><header><div><strong>{item.name}</strong><span>{formatDate(item.starts_at)} — {item.ends_at?formatDate(item.ends_at):"без даты окончания"}</span></div><Status ok={item.is_active}>{item.is_active?"Включена":"Отключена"}</Status></header><div className="campaign-metrics"><span><b>{item.metrics.clicks}</b> кликов</span><span><b>{item.metrics.new_free}</b> новых Free</span><span><b>{item.metrics.paid_clients}</b> оплатили</span><span><b>{item.metrics.active_clients}</b> активны</span><span><b>{money(item.metrics.revenue_rub)}</b> выручка</span><span><b>{item.metrics.click_to_paid_percent}%</b> click → paid</span></div><div className="campaign-link"><code>{item.deep_link}</code><button type="button" onClick={()=>void copy(item.deep_link)}>Копировать</button></div></article>):<article className="empty-record"><strong>Кампаний пока нет</strong><p>Создайте первую кампанию — статистика начнёт собираться после переходов по её deep link.</p></article>}</div></div></>}

function Plans({plans,readiness,reload}:{plans:any;readiness:any;reload():Promise<void>}){const business=plans?.plans?.find((item:any)=>item.slug==="business");const save=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const values=new FormData(e.currentTarget);await adminApi(`/plans/${business.id}/pricing`,{method:"POST",body:JSON.stringify({price_rub:values.get("price_rub")||null,price_xtr:Number(values.get("price_xtr"))||null,referral_base_rub:values.get("referral_base_rub")||null,calculation_price_rub:values.get("calculation_price_rub")||null,crypto_pay_enabled:values.get("crypto_pay_enabled")==="on",stars_enabled:values.get("stars_enabled")==="on"})});await reload()};return <><div className="readiness"><article><Status ok={readiness?.crypto_pay?.api_token_configured&&readiness?.crypto_pay?.webhook_secret_configured}>Crypto Pay</Status><p>{readiness?.crypto_pay?.production_api?"Production API":"Test API"} · token {readiness?.crypto_pay?.api_token_configured?"настроен":"не настроен"} · webhook {readiness?.crypto_pay?.webhook_secret_configured?"настроен":"не настроен"}</p></article><article><Status ok={readiness?.telegram_stars?.interface_bot_configured}>Telegram Stars</Status><p>Интерфейсный бот {readiness?.telegram_stars?.interface_bot_configured?"готов принимать платежи":"не настроен"}</p></article></div>{business&&<form className="pricing-form" onSubmit={save}><header><div><span className="eyebrow">BUSINESS</span><h2>Матрица цены</h2></div><b>30 дней</b></header><div><Field label="Цена Crypto Pay, ₽" help="Invoice создаётся в RUB с оплатой разрешённым активом."><input name="price_rub" type="number" min="0.01" step="0.01" defaultValue={business.price_rub||""}/></Field><Field label="Цена Stars, XTR" help="Целое число Telegram Stars."><input name="price_xtr" type="number" min="1" defaultValue={business.price_xtr||""}/></Field><Field label="Referral base, ₽" help="RUB-база, от которой считается партнёрская комиссия Stars."><input name="referral_base_rub" type="number" min="0.01" step="0.01" defaultValue={business.referral_base_rub||""}/></Field><Field label="Расчётная цена, ₽" help="Используется только для WRR: цена × активные платные × 12 / 52. На checkout не влияет."><input name="calculation_price_rub" type="number" min="0.01" step="0.01" defaultValue={business.calculation_price_rub||""}/></Field></div><label className="check"><input name="crypto_pay_enabled" type="checkbox" defaultChecked={business.crypto_pay_enabled}/> Разрешить Crypto Pay checkout</label><label className="check"><input name="stars_enabled" type="checkbox" defaultChecked={business.stars_enabled}/> Разрешить Telegram Stars checkout</label><button className="button acid">Сохранить тариф</button></form>}</>}

export function AdminApp(){
  const leaveGuard=useRef<import("./editor/exit-dialog").LeaveGuard|null>(null);
  const [section,setSection]=useState<Section>("Обзор");
  const [dashboard,setDashboard]=useState<any>(null);
  const [content,setContent]=useState<any>(null);
  const [ads,setAds]=useState<any>(null);
  const [plans,setPlans]=useState<any>(null);
  const [readiness,setReadiness]=useState<any>(null);
  const [requiredChannel,setRequiredChannel]=useState<any>(null);
  const [days,setDays]=useState(30);
  const [error,setError]=useState("");
  const [refreshToken,setRefreshToken]=useState(0);
  const reload=async()=>{
    setError("");
    try{
      const [d,c,a,p,r,channel]=await Promise.all([
        adminApi<any>(`/dashboard?days=${days}`), adminApi<any>("/content"),
        adminApi<any>("/advertising"), adminApi<any>("/plans"),
        adminApi<any>("/payments/readiness"), adminApi<any>("/required-channel"),
      ]);
      setDashboard(d);setContent(c);setAds(a);setPlans(p);setReadiness(r);
      setRequiredChannel(channel);setRefreshToken(v=>v+1);
    }catch(e){setError((e as Error).message)}
  };
  useEffect(()=>{void reload()},[days]);
  const submit=async(event:React.FormEvent<HTMLFormElement>,path:string)=>{
    event.preventDefault();const target=event.currentTarget;const form=new FormData(target);
    const body:Record<string,unknown>=Object.fromEntries(form.entries());
    for(const [key,value] of Object.entries(body)){
      if(key.endsWith("_at")&&typeof value==="string"&&value)body[key]=new Date(value).toISOString();
      if(["sort_order","weight","price_xtr","duration_seconds"].includes(key))body[key]=value===""?null:Number(value);
      if(["price_rub","referral_base_rub","calculation_price_rub"].includes(key)&&value==="")body[key]=null;
      if(["is_active","is_onboarding","crypto_pay_enabled","stars_enabled"].includes(key))body[key]=value==="true";
    }
    try{await adminApi(path,{method:"POST",body:JSON.stringify(body)});target.reset();await reload()}
    catch(e){setError((e as Error).message)}
  };
  return <div className="admin-shell control-v2"><aside><Logo/><nav>{sections.map(item=><button className={section===item.name?"active":""} onClick={()=>{const leave=()=>setSection(item.name);leaveGuard.current?leaveGuard.current(leave):leave()}} key={item.name}><b>{item.label}</b><small>{item.hint}</small></button>)}</nav><div className="secure"><i/>SSO · Authentik<br/><small>Доступ по группам</small></div></aside><main>{error&&<ErrorBox message={error} onClose={()=>setError("")}/>}<SectionIntro section={section}/>{section==="Шаблоны"&&<AdminCatalog onLeaveGuard={guard=>{leaveGuard.current=guard}}/>}{section==="Обзор"&&<Dashboard data={dashboard} setDays={setDays}/>} {section==="Пользователи"&&<Owners refreshToken={refreshToken}/>} {section==="Инвойсы"&&<Invoices/>} {section==="Кампании"&&<Campaigns/>} {section==="Видеообучение"&&<ContentAdmin content={content} reload={reload} submit={submit}/>} {section==="Коммуникации"&&<><RequiredChannel value={requiredChannel} reload={reload}/><Communications content={content} reload={reload} submit={submit}/></>} {section==="Реклама"&&<Advertising ads={ads} reload={reload} submit={submit}/>} {section==="Тарифы"&&<Plans plans={plans} readiness={readiness} reload={reload}/>}</main></div>
}
